import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import "./common_module.css";
import fetcher from "../lib/fetcher";

interface PublicArticle {
  id: number;
  title: string;
  excerpt: string | null;
  thumbnail: string | null;
  authorDisplayName: string;
  publishedAt: string | null;
  tags: string[];
}

interface PublicArticlesResponse {
  page: number;
  size: number;
  totalElements: number;
  items: PublicArticle[];
}

interface TagItem {
  name: string;
  count: number;
}

export default function PublicHome() {
  const router = useRouter();
  const [articles, setArticles] = useState<PublicArticle[]>([]);
  const [tags, setTags] = useState<TagItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [articlesRes, tagsRes] = await Promise.all([
          fetcher<PublicArticlesResponse>("/api/v1/public/knowledge?page=0&size=10", { skipAuth: true }),
          fetcher<TagItem[]>("/api/v1/public/tags", { skipAuth: true }),
        ]);
        setArticles(articlesRes.items);
        setTags(tagsRes);
      } catch (e) {
        setError("データの取得に失敗しました。");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const featuredArticle = articles[0] ?? null;
  const listArticles = articles.slice(1, 3);

  return (
    <div className="scr12-root">
      <header className="scr12-topbar container">
        <div className="brand">Ginga ナレッジ</div>
