              <>
                <div className="title">{featuredArticle.title}</div>
                <div className="desc">
                  {featuredArticle.excerpt ?? "社内で共有されている注目記事をピックアップ。ログインして全容を確認しましょう。"}
                </div>
              </>
            ) : (
              <>
                <div className="title">今週の注目 — AIで効率化する記事まとめ</div>
                <div className="desc">社内で共有されている注目記事をピックアップ。ログインして全容を確認しましょう。</div>
              </>
            )}
